<script setup lang="ts">
import {ref,onMounted} from 'vue';import type {Model,Building} from '../../api/types';import {getDispatchTravel,saveDispatchTravel,type DispatchTravel} from '../../api/dispatch';import {errorText,notify} from '../../ui';import Drawer from '../Drawer.vue';
const props=defineProps<{buildings:Building[]}>();defineEmits<{close:[];saved:[]}>();
type Row=Model<'DispatchTravelLink'>&{draftMinutes:number;saving:boolean;error:string};
const travel=ref<DispatchTravel>(),rows=ref<Row[]>([]),error=ref(''),loading=ref(true);
const buildingName=(id:string)=>props.buildings.find(b=>b.id===id)?.name||'未命名楼栋';
async function load(){loading.value=true;error.value='';try{travel.value=await getDispatchTravel();rows.value=travel.value.links.map(link=>({...link,draftMinutes:link.minutes,saving:false,error:''}));}catch(e){error.value=errorText(e);}finally{loading.value=false;}}
async function save(row:Row){if(!Number.isInteger(row.draftMinutes)||row.draftMinutes<0||row.draftMinutes>240){row.error='请填写0–240之间的整数分钟';return;}row.saving=true;row.error='';try{const updated=await saveDispatchTravel(row.fromBuildingId,row.toBuildingId,{minutes:row.draftMinutes,expectedVersion:row.version});Object.assign(row,updated,{draftMinutes:updated.minutes});notify('楼栋间通行时间已保存，剩余路线将自动重算');}catch(e){row.error=errorText(e);}finally{row.saving=false;}}
onMounted(load);
</script>
<template><Drawer title="通行时间配置" :busy="rows.some(r=>r.saving)" :dirty="rows.some(r=>r.minutes!==r.draftMinutes)" @close="$emit('close')"><p class="info-note">配置负责楼栋之间的步行时间。路线以楼栋和楼层粒度估算，房号不直接作为距离。</p><p v-if="loading" class="loading">正在读取通行时间…</p><p v-if="error" class="error-banner">{{error}}<button @click="load">重试</button></p><dl v-if="travel" class="details dispatch-travel-defaults"><div><dt>上下楼层</dt><dd>{{travel.floorMinutes}} 分钟 / 层</dd></div><div><dt>同层访问</dt><dd>{{travel.sameFloorMinutes}} 分钟</dd></div></dl><section v-for="row in rows" :key="row.fromBuildingId+'-'+row.toBuildingId" class="dispatch-travel-row"><form @submit.prevent="save(row)"><label>{{buildingName(row.fromBuildingId)}} → {{buildingName(row.toBuildingId)}}<small>{{row.estimated?'默认估算':'已人工配置'}}</small></label><div class="button-row"><input v-model.number="row.draftMinutes" :aria-label="buildingName(row.fromBuildingId)+'至'+buildingName(row.toBuildingId)+'分钟'" type="number" min="0" max="240" step="1" required><span>分钟</span><button class="btn" :disabled="row.saving||row.draftMinutes===row.minutes">{{row.saving?'保存中…':'保存'}}</button></div></form><p v-if="row.error" class="error-banner">{{row.error}}</p></section><p v-if="!loading&&!rows.length" class="empty-state">当前负责范围内没有需要配置的跨楼栋通行路径。</p></Drawer></template>
